    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _test(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        a = bound(a, 0, 1000000000000000000000000000000);
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 3 * a);
        try c.play{value: a}() {} catch { return; }
        try c.play{value: a}() {} catch { return; }
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        try c.play{value: a}() {} catch { return; }
        assertTrue(c.pot() == 0 || c.pot() >= potBefore + a);
